import React, { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import { CiShoppingCart } from "react-icons/ci";
import { Button } from '@mui/material';
import { LuLoaderCircle, LuSun, LuMoon, LuMenu, LuX } from "react-icons/lu";
import axios from 'axios';
import { setUser } from "../redux/userSlice";
import { useDispatch, useSelector } from "react-redux"
import { toast } from 'react-toastify';
import { useCartContext } from "../CartContext";

const Navbar = () => {

  const user = useSelector(store => store.user.user)
  const admin = user?.role === "admin" ? true : false
  const worker = user?.role === "worker" ? true : false

  const [loading, setLoading] = useState(false);
  const [theme, setTheme] = useState('light');
  const [menuOpen, setMenuOpen] = useState(false);

  const dispatch = useDispatch();
  const accessToken = localStorage.getItem('accessToken');
  const { cart } = useCartContext();

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme') || 'light';
    setTheme(savedTheme);
    document.documentElement.classList.toggle('dark', savedTheme === 'dark');
  }, []);

  const toggleTheme = () => {
    const newTheme = theme === 'light' ? 'dark' : 'light';
    setTheme(newTheme);
    localStorage.setItem('theme', newTheme);
    document.documentElement.classList.toggle('dark', newTheme === 'dark');
  };

  const handleLogout = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const res = await axios.post(
        `${import.meta.env.VITE_API_URL}/user/logout`,
        {},
        {
          headers: {
            "Authorization": `Bearer ${accessToken}`
          }
        }
      );

      if (res.data.success) {
        toast.success(res.data.message);
        dispatch(setUser(null));
        localStorage.removeItem('accessToken');
        localStorage.removeItem('user');

        setTimeout(() => setLoading(false), 1500);
      }

    } catch (error) {
      toast.error(error.response?.data?.message || "Logout failed");
      if (error.response?.status === 401) {
        dispatch(setUser(null));
        localStorage.removeItem('accessToken');
        localStorage.removeItem('user');
        window.location.href = "/login";
      }
    }
  };

  return (
    <header className='bg-[var(--color-background)] fixed w-full top-0 z-50 border border-[var(--color-border-primary)] shadow-[var(--shadow-soft)]'>

      <div className='  mx-auto flex justify-between items-center  md:py-3  px-4  md:px-8 lg:px-16'>
        {/* Logo */}
        <img
          className="w-[100px] rounded-full cursor-pointer"
          src={theme === "dark" ? "/logo.png" : "/logo2.png"}
          alt="logo"
        />
        {/* Desktop Nav */}
        <nav className='hidden md:flex gap-6 items-center'>

          <ul className="flex gap-7 text-lg font-semibold">
            <Link to="/"><li>Home</li></Link>
            {!worker && <Link to="/products"><li>Products</li></Link>}

            {user && !worker && (
              <li>
                <Link to={`/profile/${user?._id}`}>
                  Hello, {user?.firstName}
                </Link>
              </li>
            )}

            {(admin || worker) && (
              <li>
                <Link to="/dashboard/insights">Dashboard</Link>
              </li>
            )}
          </ul>

          {/* Cart - hide for workers */}
          {!worker && (
            <Link to="/cart" className='relative text-2xl'>
              <CiShoppingCart />
              <span className="bg-primary text-white rounded-full absolute -top-3 -right-4 px-2 text-sm">
                {cart?.items?.length || 0}
              </span>
            </Link>
          )}

          {/* Theme */}
          <button onClick={toggleTheme} className='text-2xl p-2 rounded-full hover:bg-primary/10'>
            {theme === 'light' ? <LuMoon /> : <LuSun />}
          </button>

          {/* Auth */}
          {user ? (
            <div className='flex gap-3 items-center'>
              <Link to="/login">
                <Button
                  variant="outlined"
                  sx={{
                    py: 1,
                    px: 2,
                    color: "#1e3a8a",
                    borderColor: "#1e3a8a",
                    "&:hover": { backgroundColor: "#0f172a", color: "#fff", borderColor: "#0f172a" }
                  }}
                >
                  Login
                </Button>
              </Link>
              <Button
                onClick={handleLogout}
                variant="contained"
                sx={{
                  py: 1,
                  px: 2,
                  backgroundColor: "#1e3a8a",
                  "&:hover": { backgroundColor: "#0f172a" }
                }}
              >
                {loading ? <LuLoaderCircle className="animate-spin" /> : "Logout"}
              </Button>
            </div>
          ) : (
            <Link to="/login">
              <Button
                variant="contained"
                sx={{
                  py: 1,
                  px: 2,
                  backgroundColor: "#1e3a8a",
                  "&:hover": { backgroundColor: "#0f172a" }
                }}
              >
                Login
              </Button>
            </Link>
          )}
        </nav>

        {/* Mobile Menu Button */}
        <button
          className='md:hidden text-3xl'
          onClick={() => setMenuOpen(true)}
        >
          <LuMenu />
        </button>
      </div>

      {/* MOBILE SIDEBAR */}
      <div className={`fixed top-0 right-0 h-full w-72 bg-[var(--color-background)]  border-1 border-white md:border-hidden shadow-lg transform transition-transform duration-300 z-50
        ${menuOpen ? "translate-x-0" : "translate-x-full"}`}>

        {/* Close Button */}
        <div className='flex justify-between items-center p-4 border-b'>
          <h2 className='font-bold'>Menu</h2>
          <button onClick={() => setMenuOpen(false)} className='text-2xl'>
            <LuX />
          </button>
        </div>

        {/* Links */}
        <div className='flex flex-col gap-5 p-4 text-lg font-medium'>

          <Link onClick={() => setMenuOpen(false)} to="/">Home</Link>
          {!worker && <Link onClick={() => setMenuOpen(false)} to="/products">Products</Link>}

          {user && (
            <Link onClick={() => setMenuOpen(false)} to={`/profile/${user?._id}`}>
              Profile
            </Link>
          )}

          {(admin || worker) && (
            <Link onClick={() => setMenuOpen(false)} to="/dashboard/insights">
              Dashboard
            </Link>
          )}

          {!worker && <Link onClick={() => setMenuOpen(false)} to="/cart">
            Cart ({cart?.items?.length || 0})
          </Link>}

          {/* Theme */}
          <button onClick={toggleTheme} className='text-left'>
            Toggle Theme
          </button>

          {/* Auth */}
          {user ? (
            <>
              <Link onClick={() => setMenuOpen(false)} to="/login">
                Login
              </Link>
              <button onClick={handleLogout} className='text-left text-red-500'>
                Logout
              </button>
            </>
          ) : (
            <Link onClick={() => setMenuOpen(false)} to="/login">
              Login
            </Link>
          )}
        </div>
      </div>

      {/* BACKDROP */}
      {menuOpen && (
        <div
          className='fixed inset-0 bg-black/40 z-40'
          onClick={() => setMenuOpen(false)}
        />
      )}
    </header>
  )
}

export default Navbar;

import React, { useState, useEffect } from 'react';
import { NavLink, useNavigate, useLocation } from 'react-router-dom';
import { LuLayoutDashboard, LuPackagePlus, LuPackageSearch } from "react-icons/lu";
import { FaUsers, FaBars, FaTimes } from "react-icons/fa";
import { TbBorderStyle } from "react-icons/tb";
import { useSelector } from "react-redux";

const Sidebar = () => {

  const [open, setOpen] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const user = useSelector(store => store.user.user);
  const isWorker = user?.role === "worker";

  // 🚀 AUTO REDIRECT ON FIRST LOAD
  useEffect(() => {
    if (location.pathname === "/dashboard") {
      navigate("/dashboard/insights", { replace: true });
    }
  }, []);

  const linkClass = ({ isActive }) =>
    `text-lg flex items-center gap-2 cursor-pointer px-3 py-3 rounded-xl transition-colors
    ${isActive
      ? "bg-[var(--color-primary)] text-white"
      : "hover:bg-[var(--color-primary)]/10 text-[var(--color-text)]"
    }`;

  return (
    <>

      {/* TOP BAR (MOBILE ONLY TOGGLE) */}
      <div className="md:hidden flex items-center p-4 pt-20 border-b border-[var(--color-border-primary)] bg-[var(--color-background)]">

        <button
          onClick={() => setOpen(!open)}
          className="p-2 rounded-md bg-[var(--color-primary)] text-white"
        >
          {open ? <FaTimes /> : <FaBars />}
        </button>

      </div>

      {/* SIDEBAR */}
      <div className={`
        fixed md:static top-0 left-0 z-50
        h-full md:h-screen
        w-[260px]
        bg-[var(--color-background)]
        border-r border-[var(--color-border-primary)]
        p-5 space-y-4
        transform transition-transform duration-300 ease-in-out
        ${open ? "translate-x-0" : "-translate-x-full md:translate-x-0"}
      `}>

        <div className="pt-6 md:pt-24 space-y-2">

          <NavLink to="/dashboard/insights" className={linkClass}>
            <LuLayoutDashboard /><span>Insights</span>
          </NavLink>

          {!isWorker && (
            <>

              <NavLink to="/dashboard/users" className={linkClass}>
                <FaUsers /><span>Users</span>
              </NavLink>
            </>
          )}
          <NavLink to="/dashboard/add-products" className={linkClass}>
            <LuPackagePlus /><span>Add Product</span>
          </NavLink>

          <NavLink to="/dashboard/products" className={linkClass}>
            <LuPackageSearch /><span>Products</span>
          </NavLink>
          <NavLink to="/dashboard/orders" className={linkClass}>
            <TbBorderStyle /><span>Orders</span>
          </NavLink>

        </div>

      </div>

      {/* BACKDROP */}
      {open && (
        <div
          onClick={() => setOpen(false)}
          className="fixed inset-0 bg-black/40 md:hidden z-40"
        />
      )}

    </>
  );
};

export default Sidebar;

import React, { useState } from 'react';
import { useDispatch } from "react-redux";
import { RiDeleteBinLine } from "react-icons/ri";
import { Link, useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import { CiShoppingCart } from "react-icons/ci";
import axios from 'axios';
import { setCart } from '../redux/productSlice';
import { Snackbar, Alert } from "@mui/material";
import { useCartContext } from "../CartContext";
import {
  updateGuestCartQuantity,
  removeFromGuestCart
} from '../utils/guestCart';
import { getErrorMessage } from '../utils/errorMessage';

const Cart = () => {

  const accessToken = localStorage.getItem("accessToken");
  const { cart } = useCartContext();
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const [toastState, setToastState] = useState({
    open: false,
    message: "",
    severity: "success"
  });

  const API = `${import.meta.env.VITE_API_URL}/cart`;

  const updateQuantity = async (productId, type) => {
    try {
      if (!accessToken) {
        const newCart = updateGuestCartQuantity(productId, type);
        dispatch(setCart(newCart));
        setToastState({
          open: true,
          message: "Quantity Updated",
          severity: "success"
        });
        return;
      }

      const res = await axios.put(
        `${API}/update`,
        { productId, type },
        {
          headers: {
            Authorization: `Bearer ${accessToken}`
          }
        }
      );

      if (res.data.success) {

        dispatch(setCart(res.data.cart));

        setToastState({
          open: true,
          message: "Quantity Updated",
          severity: "success"
        });
      }

    } catch (error) {

      setToastState({
        open: true,
        message: getErrorMessage(error, "Quantity cannot be updated"),
        severity: "error"
      });

    }
  };

  const handleRemove = async (productId) => {

    try {
      if (!accessToken) {
        const newCart = removeFromGuestCart(productId);
        dispatch(setCart(newCart));
        setToastState({
          open: true,
          message: "Product removed from cart",
          severity: "success"
        });
        return;
      }

      const res = await axios.delete(`${API}/remove`, {
        headers: {
          Authorization: `Bearer ${accessToken}`
        },
        data: { productId }
      });

      if (res.data.success) {

        dispatch(setCart(res.data.cart));

        setToastState({
          open: true,
          message: "Product removed from cart",
          severity: "success"
        });

      }

    } catch (error) {

      setToastState({
        open: true,
        message: "Cannot remove product",
        severity: "error"
      });

    }
  };

  // Shipping is not charged automatically: it is agreed with the buyer on
  // WhatsApp before the order is confirmed. Only the product subtotal is shown.
  const subTotal = cart?.totalPrice || 0;

  return (

    <div className='bg-[var(--color-background)] min-h-screen'>

      <Navbar />

      {cart?.items?.length > 0 ? (

        <div className='w-full max-w-screen-2xl mx-auto pt-28 px-4 sm:px-6 flex flex-col md:flex-row gap-8 md:gap-16 lg:gap-24'>

          {/* LEFT SIDE */}
          <div className='flex flex-col gap-5 flex-1 w-full'>

            <h1 className='text-2xl text-text dark:text-text-dark mb-4 font-bold'>
              Shopping Cart
            </h1>

            {cart.items.map((product, index) => (

              <div
                key={index}
                className="
                  p-4 flex flex-col md:flex-row md:justify-between md:items-center gap-4
                  bg-white/80 dark:bg-white/10
                  backdrop-blur-md
                  border border-gray-200 dark:border-white/10
                  rounded-lg shadow-sm text-black
                "
              >

                {/* PRODUCT */}
                <div className="flex items-center gap-4 w-full md:w-[350px] min-w-0">

                  <img
                    src={product?.productId?.productImg?.[0]?.url || '/logo.png'}
                    className="w-20 h-20 object-cover rounded flex-shrink-0"
                    alt=""
                  />

                  <div className="w-full min-w-0">

                    <h1
                      className="
                        font-semibold
                        text-text dark:text-text-dark
                        break-words
                      "
                    >
                      {product?.productId?.productName}
                    </h1>

                    <p
                      className="
                        font-semibold
                        text-text dark:text-text-dark
                        break-words
                      "
                    >
                      PKR {product?.productId?.productPrice}
                    </p>

                  </div>

                </div>

                {/* QUANTITY */}
                <div className="flex gap-3 items-center md:justify-start">

                  <button
                    className='bg-blue-600 px-3 py-1 text-white rounded hover:bg-blue-700 transition'
                    onClick={() =>
                      updateQuantity(product.productId._id, "decrease")
                    }
                  >
                    -
                  </button>

                  <span className='text-text dark:text-text-dark'>
                    {product.quantity}
                  </span>

                  <button
                    className='bg-blue-600 px-3 py-1 text-white rounded hover:bg-blue-700 transition'
                    onClick={() =>
                      updateQuantity(product.productId._id, "increase")
                    }
                  >
                    +
                  </button>

                </div>

                {/* PRICE */}
                <p className='w-full md:w-[120px] md:text-right text-text dark:text-text-dark'>
                  PKR {(product?.productId?.productPrice * product.quantity).toLocaleString()}
                </p>

                {/* REMOVE */}
                <p
                  onClick={() => handleRemove(product?.productId?._id)}
                  className='flex text-red-500 items-center gap-1 cursor-pointer md:justify-end'
                >
                  <RiDeleteBinLine />
                  Remove
                </p>

              </div>

            ))}

          </div>

          {/* RIGHT SIDE */}
          <div className='w-full md:w-[350px]'>

            <div
              className="
                p-5 h-fit
                bg-white/80 dark:bg-white/10
                backdrop-blur-md
                border border-gray-200 dark:border-white/10
                rounded-lg shadow-md
                text-black
              "
            >

              <h1 className='font-bold text-xl mb-4 text-text dark:text-text-dark'>
                Order Summary
              </h1>

              <div className='space-y-4 text-text dark:text-text-dark'>

                <div className="flex justify-between font-bold">
                  <span>Subtotal ({cart?.items?.length} items)</span>
                  <span>PKR {subTotal.toLocaleString()}</span>
                </div>

                <p className="text-sm text-gray-500 dark:text-gray-400">
                  Shipping charges will be communicated through WhatsApp before order confirmation.
                </p>

              </div>

              <div className='mt-6'>

                <button
                  onClick={() => navigate(`/address`)}
                  className='btn-primary mt-4 w-full'
                >
                  Place Order
                </button>

                <Link to="/products">

                  <button className='btn-primary mt-2 w-full'>
                    Continue Shopping
                  </button>

                </Link>

              </div>

              {/* INFO */}
              <div className="text-sm text-gray-500 dark:text-gray-400 pt-4">

                <p>* 30 Days Return Policy</p>
                <p>* Cash on Delivery Available</p>

              </div>

            </div>

          </div>

        </div>

      ) : (

        <div className="flex flex-col items-center justify-center min-h-screen p-6 text-center">

          <div
            className="
              bg-white/80 dark:bg-white/10
              backdrop-blur-md
              p-6 rounded-full
              border border-gray-200 dark:border-white/10
            "
          >

            <CiShoppingCart className='w-16 h-16 text-primary mx-auto' />

            <h2 className='mt-6 text-2xl font-bold text-text dark:text-text-dark'>
              Your Cart is Empty
            </h2>

            <p className='mt-2 text-gray-600 dark:text-gray-400'>
              Looks like you haven't added anything yet!
            </p>

            <Link to="/products">

              <button className='btn-primary mt-6'>
                Continue Shopping
              </button>

            </Link>

          </div>

        </div>

      )}

      {/* TOAST */}
      <Snackbar
        open={toastState.open}
        autoHideDuration={3000}
        onClose={() =>
          setToastState({
            ...toastState,
            open: false
          })
        }
        anchorOrigin={{
          vertical: "top",
          horizontal: "right"
        }}
      >

        <Alert
          severity={toastState.severity}
          onClose={() =>
            setToastState({
              ...toastState,
              open: false
            })
          }
          variant="filled"
        >
          {toastState.message}
        </Alert>

      </Snackbar>

    </div>

  );
};

export default Cart;

import React, { useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { FaCheckCircle } from "react-icons/fa";
import axios from 'axios';
import { Snackbar, Alert } from "@mui/material";

const OrderSuccess = () => {
    const navigate = useNavigate();
    const { orderId } = useParams();
    const [loading, setLoading] = useState(false);

    const [toast, setToast] = useState({
        open: false,
        message: "",
        severity: "success"
    });

    const inquireOrder = async () => {
        setLoading(true);
        try {
            const token = localStorage.getItem("accessToken");

            await axios.post(
                `${import.meta.env.VITE_API_URL}/orders/inquire`,
                { orderId },
                {
                    headers: {
                        Authorization: `Bearer ${token}`
                    }
                }
            );

            setToast({
                open: true,
                message: "Inquiry sent to admin. They will respond via email.",
                severity: "success"
            });
        } catch (error) {
            setToast({
                open: true,
                message: "Failed to send inquiry",
                severity: "error"
            });
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center bg-gray-100 px-4">

            <div className="w-[420px] bg-white rounded-2xl shadow-lg p-8 text-center">

                {/* BIG ICON */}
                <div className="flex justify-center mb-6">
                    <FaCheckCircle className="text-green-500 text-7xl animate-pulse" />
                </div>

                {/* TITLE */}
                <h1 className="text-2xl font-bold text-gray-800 mb-2">
                    Order Created Successfully
                </h1>

                <p className="text-gray-500 mb-6">
                    Your COD order has been placed successfully. We will confirm delivery details shortly.
                </p>

                <div className="space-y-3">
                    <button
                        onClick={() => navigate('/products')}
                        className="w-full bg-pink-600 hover:bg-pink-700 text-white font-semibold py-2 rounded-lg transition"
                    >
                        Continue Shopping
                    </button>
                    
                    <button
                        onClick={inquireOrder}
                        disabled={loading}
                        className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 rounded-lg transition disabled:opacity-50"
                    >
                        {loading ? "Sending..." : "Inquire Order"}
                    </button>
                </div>

            </div>

            {/* TOAST */}
            <Snackbar
                open={toast.open}
                autoHideDuration={3000}
                onClose={() => setToast({ ...toast, open: false })}
                anchorOrigin={{ vertical: "top", horizontal: "right" }}
            >
                <Alert
                    severity={toast.severity}
                    variant="filled"
                    onClose={() => setToast({ ...toast, open: false })}
                >
                    {toast.message}
                </Alert>
            </Snackbar>

        </div>
    );
};

export default OrderSuccess;

import ProductCard from '../components/ProductCard';
import FilterSideBar from '../components/FilterSideBar';
import LoaderScreen from '../components/LoaderScreen';
import Box from '@mui/material/Box';
import MenuItem from '@mui/material/MenuItem';
import FormControl from '@mui/material/FormControl';
import Select from '@mui/material/Select';
import { useState, useEffect } from 'react';
import axios from 'axios';
import { Snackbar, Alert, Drawer, Button } from "@mui/material";
import { setProducts } from '../redux/productSlice';
import { useSelector, useDispatch } from 'react-redux';
import Navbar from '../components/Navbar';
import { LuFilter } from "react-icons/lu";

const Products = () => {
    const [isDarkTheme, setIsDarkTheme] = useState(false);

    const products = useSelector(store => store?.products?.products || []);

    const [filter, setFilter] = useState('');
    const [allProducts, setAllProducts] = useState([]);
    const [search, setSearch] = useState("");
    const [category, setCategory] = useState("All");
    const [brand, setBrand] = useState("All");
    const [loading, setLoading] = useState(true);
    const [priceRange, setPriceRange] = useState([0, 10000]);
    const [displayOrder] = useState('lowToHigh');

    // MOBILE FILTER DRAWER
    const [openFilter, setOpenFilter] = useState(false);

    const dispatch = useDispatch();

