import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import Tabs from '../components/Tabs';
import { useSelector, useDispatch } from 'react-redux';
import userLogo from "../assets/userLogo.png";
import axios from 'axios';
import { setUser } from '../redux/userSlice';
import { Snackbar, Alert } from "@mui/material";

const Profile = () => {

  const { userId } = useParams();
  const navigate = useNavigate();
  const dispatch = useDispatch();

  const { user } = useSelector(store => store.user);

  const [userOrder, setUserOrder] = useState(null);
  const [loading, setLoading] = useState(false);
  const [file, setFile] = useState(null);

  const [toastState, setToastState] = useState({
    open: false,
    message: "",
    severity: "success"
  });

  const [updateUser, setUpdateUser] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNo: "",
    address: "",
    city: "",
    zipCode: "",
    profilePic: "",
    role: ""
  });

  const accessToken = localStorage.getItem("accessToken");

  useEffect(() => {
    if (user) {
      setUpdateUser({
        firstName: user.firstName || "",
        lastName: user.lastName || "",
        email: user.email || "",
        phoneNo: user.phoneNo || "",
        address: user.address || "",
        city: user.city || "",
        zipCode: user.zipCode || "",
        profilePic: user.profilePic || "",
        role: user.role || ""
      });
    }
  }, [user]);

  const getUserOrders = async () => {
    try {
      const res = await axios.get(
        `${import.meta.env.VITE_API_URL}/orders/get-my-order`,
        {
          headers: {
            Authorization: `Bearer ${accessToken}`
          }
        }
      );

      if (res.data.success) {
        setUserOrder(res.data);
      }

    } catch (err) {
      console.log(err);
    }
  };

  useEffect(() => {
    getUserOrders();
  }, []);

  const handleChange = (e) => {
    setUpdateUser({
      ...updateUser,
      [e.target.name]: e.target.value
    });
  };

  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (!selectedFile) return;

    setFile(selectedFile);
    const previewURL = URL.createObjectURL(selectedFile);

    setUpdateUser({
      ...updateUser,
      profilePic: previewURL
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const formData = new FormData();

            Object.keys(updateUser).forEach(key => {
        if (key === "role") return;
        formData.append(key, updateUser[key]);
      });

      if (file) {
        formData.append("file", file);
      }

      const res = await axios.put(
        `${import.meta.env.VITE_API_URL}/user/update/${userId}`,
        formData,
        {
          headers: {
            Authorization: `Bearer ${accessToken}`,
            "Content-Type": "multipart/form-data"
          }
        }
      );

      if (res.data.success) {
        dispatch(setUser(res.data.user));

        setToastState({
          open: true,
          message: "Profile Updated Successfully",
          severity: "success"
        });

        setTimeout(() => navigate("/"), 1200);
      }

    } catch (error) {
      setToastState({
        open: true,
        message: error.response?.data?.message || "Update Failed",
        severity: "error"
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      {/* PAGE WRAPPER */}
      <div className="pt-20 min-h-screen bg-[var(--color-background)] px-3 md:px-6">

        <div className="max-w-7xl mx-auto">

          {/* RESPONSIVE CARD WRAPPER */}
          <div className="bg-white/5 dark:bg-white/5 backdrop-blur border border-white/10 rounded-xl p-3 md:p-6">

            <Tabs
              profilePic={updateUser.profilePic || userLogo}
              handleFileChange={handleFileChange}
              handleChange={handleChange}
              handleSubmit={handleSubmit}
              updateUser={updateUser}
              loading={loading}
              userOrder={userOrder}
              setUserOrder={setUserOrder}
            />

          </div>

        </div>

      </div>

      {/* TOAST */}
      <Snackbar
        open={toastState.open}
        autoHideDuration={3000}
        onClose={() => setToastState({ ...toastState, open: false })}
        anchorOrigin={{ vertical: "top", horizontal: "right" }}
      >
        <Alert
          severity={toastState.severity}
          variant="filled"
          onClose={() => setToastState({ ...toastState, open: false })}
        >
          {toastState.message}
        </Alert>
      </Snackbar>
    </>
  );
};

export default Profile;

import React, { useEffect, useState } from 'react';
import axios from 'axios';

import {
  ResponsiveContainer,
  LineChart,
  Line,
  Tooltip,
  XAxis,
  YAxis,
  CartesianGrid
} from "recharts";

const AdminSales = () => {

  const [states, setStates] = useState({
    totalUsers: 0,
    totalProducts: 0,
    totalOrders: 0,
    totalSales: 0,
    salesByDate: []
  });

  const accessToken = localStorage.getItem("accessToken");

  const fetchStates = async () => {
    try {

      const res = await axios.get(
        `${import.meta.env.VITE_API_URL}/orders/sales`,
        {
          headers: {
            Authorization: `Bearer ${accessToken}`
          }
        }
      );

      if (res.data.success) {

        const formattedSales = (res.data.sales || []).map(item => ({
          date: new Date(item.date).toLocaleDateString("en-US", {
            month: "short",
            day: "numeric"
          }),
          amount: item.amount
        }));

        setStates({
          totalUsers: res.data.totalUsers || 0,
          totalProducts: res.data.totalProducts || 0,
          totalOrders: res.data.totalOrders || 0,
          totalSales: res.data.totalSales || 0,
          salesByDate: formattedSales
        });
      }

    } catch (error) {
      console.log("ERROR FETCHING SALES:", error);
    }
  };

  useEffect(() => {
    fetchStates();
  }, []);

  return (
    <div className="
      min-h-screen
      bg-[var(--color-background)]
      text-[var(--color-text)]
      px-4 sm:px-6 lg:px-10 pt-8
      md:pt-32
    ">

      {/* ================= STATS ================= */}
      <div className="
        grid
        grid-cols-1
        sm:grid-cols-2
        lg:grid-cols-4
        gap-4 lg:gap-6
      ">

        <div className="bg-white/10 backdrop-blur-md rounded-xl p-5 shadow">
          <h1 className="text-sm font-medium opacity-80">
            Total Users
          </h1>

          <div className="mt-2 text-2xl font-bold">
            {states.totalUsers}
          </div>
        </div>

        <div className="bg-white/10 backdrop-blur-md rounded-xl p-5 shadow">
          <h1 className="text-sm font-medium opacity-80">
            Total Products
          </h1>

          <div className="mt-2 text-2xl font-bold">
            {states.totalProducts}
          </div>
        </div>

        <div className="bg-white/10 backdrop-blur-md rounded-xl p-5 shadow">
          <h1 className="text-sm font-medium opacity-80">
            Total Orders
          </h1>

          <div className="mt-2 text-2xl font-bold">
            {states.totalOrders}
          </div>
        </div>

        <div className="bg-white/10 backdrop-blur-md rounded-xl p-5 shadow">
          <h1 className="text-sm font-medium opacity-80">
            Total Sales
          </h1>

          <div className="mt-2 text-2xl font-bold">
            PKR {states.totalSales}
          </div>
        </div>

      </div>

      {/* ================= GRAPH ================= */}
      <div className="mt-10">

        <h1 className="text-xl font-bold mb-4">
          Sales (Last 30 Days)
        </h1>

        <div className="
          h-[320px]
          bg-white/10
          backdrop-blur-md
          rounded-xl
          shadow
          p-4 sm:p-6
        ">

          <ResponsiveContainer width="100%" height="100%">

            <LineChart data={states.salesByDate}>

              <CartesianGrid
                strokeDasharray="3 3"
                opacity={0.1}
              />

              <XAxis
                dataKey="date"
                tick={{ fill: "currentColor", fontSize: 12 }}
              />

              <YAxis
                tick={{ fill: "currentColor", fontSize: 12 }}
              />

              <Tooltip />

              <Line
                type="monotone"
                dataKey="amount"
                stroke="var(--color-primary)"
                strokeWidth={3}
                dot={{ r: 4 }}
                activeDot={{ r: 7 }}
              />

            </LineChart>

          </ResponsiveContainer>

        </div>

      </div>

    </div>
  );
};

